  "Obra de ficção / história alternativa. Não representa fatos nem endosso. Progresso salvo automaticamente neste navegador, separado por cenário. Funciona offline e sem conta; com login, os saves e finais também vão para a nuvem.": "Художественный вымысел / альтернативная история. Не отражает факты и не является одобрением. Прогресс сохраняется автоматически в этом браузере, отдельно для каждого сценария. Работает офлайн и без аккаунта; после входа сохранения и концовки также попадают в облако.",
  "Escolher outro cenário": "Выбрать другой сценарий",
  "Como jogar": "Как играть",
  "Recomeçar do início": "Начать сначала",
  "Configurações: idioma, acessibilidade e som": "Настройки: язык, доступность и звук",
  "Som ligado (clique para silenciar)": "Звук включён (нажмите, чтобы выключить)",
  "Entrar para salvar na nuvem (opcional)": "Войти, чтобы сохранять в облако (необязательно)",
  "Mapa do Brasil por facção, com exércitos e ordens. Use Tab para percorrer os estados; a descrição em texto está no botão Descrição do mapa.": "Карта Бразилии по фракциям, с армиями и приказами. Перемещайтесь по штатам клавишей Tab; текстовое описание — в кнопке «Описание карты».",
  "Indisponível por enquanto": "Пока недоступно",
  "Ficção de história alternativa, no estilo de mods de jogos de estratégia. Tudo o que acontece a partir da primeira escolha é inventado: não retrata fatos, não é previsão e não representa endosso a nenhuma pessoa, partido ou ação. Personagens reais aparecem apenas em papéis públicos, sem falas atribuídas. Golpe de Estado é crime contra a democracia — no jogo, ele tem as consequências que tem.": "Альтернативная история в стиле модов для стратегий. Всё, что происходит после первого выбора, выдумано: это не факты, не прогноз и не одобрение какого-либо человека, партии или действия. Реальные люди появляются только в публичных ролях, без приписанных им реплик. Государственный переворот — преступление против демократии, и в игре у него соответствующие последствия.",
  "Nova campanha": "Новая кампания",
  "← Outros cenários": "← Другие сценарии",
