  "Facções": "Фракции",
  "A Apuração": "Подсчёт голосов",
  "No Palácio da Alvorada, assessores andam de um lado para o outro. Governos estrangeiros já cumprimentam o vencedor. Nas estradas, caminhões e apoiadores começam a bloquear rodovias em vários estados. Aliados no Congresso aguardam um sinal antes de se posicionar.": "Во дворце Алворада советники ходят из угла в угол. Иностранные правительства уже поздравляют победителя. На трассах грузовики и сторонники начинают перекрывать дороги в нескольких штатах. Союзники в Конгрессе ждут сигнала, прежде чем занять позицию.",
  "Você ainda não falou. O país inteiro espera.": "Вы ещё не высказались. Вся страна ждёт.",
  "Reconhecer a derrota em pronunciamento e autorizar a transição.": "Признать поражение в обращении и разрешить передачу власти.",
  "Ficar em silêncio por enquanto e deixar a base se manifestar.": "Пока промолчать и дать базе высказаться.",
  "Contestar o resultado no TSE, pedindo a anulação de parte das urnas.": "Оспорить результат в Высшем избирательном суде, требуя аннулировать часть урн.",
  "Convocar em sigilo os comandantes das Forças Armadas.": "Тайно вызвать командующих Вооружёнными силами.",
