  "Cada ação custa pontos de ação (AP) e, às vezes, Recursos. Cada uma pode ser usada uma vez por turno. Você tem": "Каждое действие стоит очков действий (ОД), а иногда и ресурсов. Каждое можно использовать раз в ход. У вас",
