  "escolha um na aba Decisões": "выберите его на вкладке «Решения»",
  "Nenhum foco nacional em andamento (aba Decisões).": "Нет текущего национального фокуса (вкладка «Решения»).",
  "Substituir o comandante do Exército por um general alinhado.": "Заменить командующего армией на лояльного генерала.",
  "Seguir em frente: publicar o decreto.": "Идти дальше: опубликовать указ.",
  "Ordenar que tropas cerquem o TSE e o Congresso.": "Приказать войскам окружить Высший избирательный суд и Конгресс.",
  "Avança o tempo e resolve economia, combates, facções e diplomacia": "Двигает время и рассчитывает экономику, бои, фракции и дипломатию",
