  "Frentes": "Фронты",
  "Selecione um exército (contador azul) e depois o estado-alvo. Cada exército recebe uma ordem por mês; até": "Выберите армию (синяя фишка), затем целевой штат. Каждая армия получает один приказ в месяц; до",
  "manobras (atacar/mover/recuar) conforme o atributo militar e a lealdade militar. Defender e reforçar não contam.": "манёвров (атака/перемещение/отход) в зависимости от военного показателя и лояльности военных. Оборона и усиление не считаются.",
