  "Clique num estado destacado no mapa ou escolha abaixo. Ordens não gastam AP e são executadas no Encerrar mês.": "Нажмите на подсвеченный штат на карте или выберите ниже. Приказы не тратят ОД и выполняются при «Завершить месяц».",
