  "Previsão da ordem": "Прогноз приказа",
  "Sem combate. Tropas paradas no próprio território recuperam moral e baixam a agitação.": "Боя нет. Войска, стоящие на своей территории, восстанавливают боевой дух и снижают волнения.",
