  "💡 Boa chance: mande o ataque com estes exércitos.": "💡 Хорошие шансы: атакуйте этими армиями.",
  "Batalha": "Бой",
  "Poder de combate inicial = força × moral × experiência × modificadores": "Начальная боевая мощь = сила × боевой дух × опыт × модификаторы",
