  "Voltar à visão geral": "Назад к обзору",
  "O Mundo Reage": "Мир реагирует",
  "Estados Unidos, União Europeia e quase todos os vizinhos sul-americanos se recusam a reconhecer o novo governo. O Mercosul suspende o Brasil, bancos estrangeiros congelam linhas de crédito e o real perde um terço do valor em duas semanas.": "США, Евросоюз и почти все южноамериканские соседи отказываются признать новое правительство. МЕРКОСУР приостанавливает членство Бразилии, иностранные банки замораживают кредитные линии, а реал за две недели теряет треть стоимости.",
  "Nos supermercados, os preços sobem dia após dia. Exportadores do agronegócio — parte da sua base — ligam desesperados: contratos estão sendo cancelados.": "В супермаркетах цены растут день за днём. Экспортёры агробизнеса — часть вашей базы — в отчаянии звонят: контракты расторгаются.",
  "Prometer eleições supervisionadas para obter reconhecimento.": "Пообещать выборы под наблюдением ради признания.",
  "Buscar apoio em governos simpáticos e ignorar o Ocidente.": "Искать поддержки у дружественных правительств и игнорировать Запад.",
  "Congelar preços e decretar controle de câmbio.": "Заморозить цены и ввести валютный контроль.",
  "toque para ver por que venceu ou perdeu": "нажмите, чтобы узнать, почему вы победили или проиграли",
