  "de força": "силы",
  "inimigas:": "противника:",
  "💡 Seus exércitos que lutaram perderam moral: dê um mês de Defender antes do próximo ataque, se puder.": "💡 Армии, участвовавшие в бою, потеряли боевой дух: если можете, дайте им месяц обороны перед следующей атакой.",
  "Pular animação": "Пропустить анимацию",
  "Rever": "Повторить",
  "Final: O Brasil Partido": "Концовка: Расколотая Бразилия",
  "Três Bandeiras": "Три флага",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul; o governo constitucional, o Norte e o Nordeste; a Liga do Sul hasteia sua própria bandeira entre o Paraná e o Uruguai. Minas Gerais continua cortada por trincheiras.": "Перемирие становится границей. Бразилиа контролирует Центр и Юг; конституционное правительство — Север и Северо-Восток; Южная лига поднимает свой флаг между Параной и Уругваем. Минас-Жерайс по-прежнему изрезан окопами.",
  "Diplomatas falam em \"conflito congelado\". Nas famílias separadas pela linha de frente, ninguém usa essa palavra. A guerra de separação que muitos julgavam impossível tornou-se o novo normal.": "Дипломаты говорят о «замороженном конфликте». В семьях, разделённых линией фронта, этого слова никто не произносит. Война за отделение, которую многие считали невозможной, стала новой нормой.",
