  "A Liga do Sul se rebela": "Южная лига восстаёт",
  "Os governadores do Sul rompem com Brasília. A revolta começa pequena — um estado e um exército modesto — e ainda pode ser contida.": "Губернаторы Юга порывают с Бразилиа. Восстание начинается с малого — один штат и скромная армия — и его ещё можно сдержать.",
  "Armistício no Sul": "Перемирие на Юге",
  "Os governadores do Sul aceitam baixar as armas. Os estados rebelados voltam ao seu controle.": "Губернаторы Юга соглашаются сложить оружие. Мятежные штаты возвращаются под ваш контроль.",
  "O exército separatista foi dissolvido.": "Армия сепаратистов распущена.",
  "Os governadores do Sul assinam o pacto: mais autonomia em troca de lealdade. A rebelião do Sul está descartada.": "Губернаторы Юга подписывают пакт: больше автономии в обмен на лояльность. Мятеж на Юге исключён.",
  "A Tensão no Sul deixa de importar: o Sul é seu aliado.": "Напряжённость на Юге больше не важна: Юг — ваш союзник.",
  "A Liga do Sul cai": "Южная лига пала",
  "Não resta nenhum estado sob controle separatista. A revolta do Sul acabou.": "Под контролем сепаратистов не осталось ни одного штата. Восстание на Юге окончено.",
  "Cúpula de Porto Alegre": "Саммит в Порту-Алегри",
  "Os governadores do Rio Grande do Sul, de Santa Catarina e do Paraná pedem uma reunião de emergência. Querem verbas, autonomia fiscal e garantias de que Brasília não mandará interventores.": "Губернаторы Риу-Гранди-ду-Сул, Санта-Катарины и Параны просят о срочной встрече. Им нужны деньги, налоговая автономия и гарантии, что Бразилиа не пришлёт интервенторов.",
  "Se nada mudar, dizem, não respondem pelo que a Liga do Sul fará.": "Если ничего не изменится, говорят они, они не отвечают за то, что сделает Южная лига.",
  "Aceitar o acordo: verbas e autonomia fiscal para o Sul.": "Принять сделку: деньги и налоговая автономия для Юга.",
  "Prometer estudar as demandas.": "Пообещать изучить требования.",
  "Ameaçar com intervenção federal.": "Пригрозить федеральным вмешательством.",
  "A Liga do Sul manda emissários": "Южная лига присылает посланников",
  "Os separatistas do Sul propõem um pacto de não agressão enquanto você enfrenta a resistência.": "Южные сепаратисты предлагают пакт о ненападении, пока вы воюете с сопротивлением.",
  "Ameaçar com uma ofensiva.": "Пригрозить наступлением.",
  "A Liga do Sul cobra a fatura": "Южная лига выставляет счёт",
  "Os separatistas exigem autonomia fiscal e comando próprio em troca da trégua.": "Сепаратисты требуют налоговой автономии и собственного командования в обмен на перемирие.",
  "Ceder e manter a trégua.": "Уступить и сохранить перемирие.",
  "Romper o pacto.": "Разорвать пакт.",
  "O que se temia acontece: o comando militar do Nordeste e unidades da Marinha declaram lealdade ao governo constitucional. Generais que antes hesitavam agora escolhem lados. Amazonas e Amapá passam para a resistência. E no Sul, os governadores do Rio Grande do Sul e de Santa Catarina — a chamada Liga do Sul — observam o racha e medem até onde Brasília ainda manda neles.": "Случилось то, чего боялись: Северо-Восточное военное командование и части флота присягают конституционному правительству. Генералы, колебавшиеся прежде, выбирают стороны. Амазонас и Амапа переходят к сопротивлению. А на Юге губернаторы Риу-Гранди-ду-Сул и Санта-Катарины — так называемая Южная лига — наблюдают за расколом и прикидывают, насколько Бразилиа ещё ими командует.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul mede forças com Brasília: se a tensão passar do limite, ela abre uma terceira frente.": "Линия фронта рассекает Минас-Жерайс и запад Баии. Экономика рушится; тысячи семей бегут в Парагвай, Боливию и Уругвай. На Юге Южная лига меряется силами с Бразилиа: если напряжённость перейдёт предел, она откроет третий фронт.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, o Pacto Federativo segura: as brigadas gaúchas e catarinenses lutam ao lado de Brasília.": "Линия фронта рассекает Минас-Жерайс и запад Баии. Экономика рушится; тысячи семей бегут в Парагвай, Боливию и Уругвай. На Юге Федеративный пакт держится: бригады Риу-Гранди-ду-Сул и Санта-Катарины сражаются на стороне Бразилиа.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul abriu uma terceira frente.": "Линия фронта рассекает Минас-Жерайс и запад Баии. Экономика рушится; тысячи семей бегут в Парагвай, Боливию и Уругвай. На Юге Южная лига открыла третий фронт.",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul e o Sul — os governadores sulistas nunca romperam —; o governo constitucional fica com o Norte e o Nordeste. Minas Gerais continua cortada por trincheiras.": "Перемирие становится границей. Бразилиа контролирует Центр и Юг — южные губернаторы так и не откололись; конституционному правительству достаются Север и Северо-Восток. Минас-Жерайс по-прежнему изрезан окопами.",
  "Duas Bandeiras": "Два флага",
  "A revolta da Liga do Sul foi esmagada: não resta estado sob controle separatista.": "Восстание Южной лиги подавлено: ни одного штата под контролем сепаратистов не осталось.",
  "Pacto Federativo assinado: o Sul agora é aliado e enviou uma divisão.": "Федеративный пакт подписан: Юг теперь союзник и прислал дивизию.",
  "Os governadores do Sul pedem uma cúpula: veja a aba História.": "Губернаторы Юга просят саммит: см. вкладку «История».",
