  "Dificuldade": "Сложность",
  "Para quem nunca jogou estratégia: inimigo mais fraco, Sul mais calmo, mais Recursos e uma interface mais simples. Os exércitos lutam sozinhos.": "Для тех, кто никогда не играл в стратегии: слабее противник, спокойнее Юг, больше ресурсов и проще интерфейс. Армии воюют сами.",
  "O jogo como foi pensado: decisões com peso e guerra equilibrada.": "Игра в задуманном виде: весомые решения и сбалансированная война.",
  "Inimigo mais forte, menos Recursos e o Sul mais inquieto. Para quem já conhece o jogo.": "Сильнее противник, меньше ресурсов и беспокойнее Юг. Для тех, кто уже знает игру.",
  "Recomendado para começar": "Рекомендуется для начала",
  "Cerca de 12 a 20 meses de jogo (turnos). A história no ritmo normal.": "Примерно 12–20 ходов. История в обычном темпе.",
  "Cerca de 8 a 11 turnos (20 a 30 minutos). O tempo passa mais depressa e os eventos-chave chegam antes.": "Примерно 8–11 ходов (20–30 минут). Время идёт быстрее, ключевые события наступают раньше.",
  "No Fácil, a interface fica mais simples: os exércitos agem sozinhos, a conversão de Recursos some e as escolhas que encerram a campanha avisam antes.": "На лёгком уровне интерфейс проще: армии действуют сами, обмен ресурсов скрыт, а выборы, завершающие кампанию, заранее предупреждают.",
  "A dificuldade fica fixa até o fim da campanha. Você pode conferir qual é em Configurações.": "Сложность фиксируется до конца кампании. Её можно посмотреть в Настройках.",
  "Começar uma nova campanha substitui a campanha salva.": "Новая кампания заменит сохранённую.",
  "Começar": "Начать",
  "Campanha atual": "Текущая кампания",
  "Interface simples": "Простой интерфейс",
  "— exércitos no automático, conversão de Recursos escondida e Diplomacia/Facções em “Mais”": "— армии на автомате, обмен ресурсов скрыт, Дипломатия/Фракции в «Ещё»",
  "A dificuldade e a duração são escolhidas ao começar uma campanha e não mudam no meio dela.": "Сложность и длительность выбираются в начале кампании и не меняются по ходу.",
  "Mais ▾": "Ещё ▾",
  "Menos ▴": "Свернуть ▴",
  "Seus exércitos lutam sozinhos.": "Ваши армии воюют сами.",
  "Todo mês, quem está sem ordem ataca onde a chance é boa e defende o resto.": "Каждый месяц армии без приказа атакуют при хороших шансах, а остальные обороняются.",
  "Todo mês, quem está sem ordem defende as fronteiras.": "Каждый месяц армии без приказа обороняют границы.",
  "As ordens automáticas estão desligadas.": "Автоприказы выключены.",
  "Seus exércitos vão ficar parados.": "Ваши армии будут стоять на месте.",
  "🤖 Ligar ordens automáticas": "🤖 Включить автоприказы",
  "Comandar manualmente": "Командовать вручную",
  "← Voltar ao resumo simples": "← Назад к простой сводке",
  "Modo simples: seus exércitos agem sozinhos. Clique num estado para ver detalhes e agir nele.": "Простой режим: ваши армии действуют сами. Нажмите на штат, чтобы увидеть детали и действовать.",
  "Modo simples: seus exércitos agem sozinhos. Toque num estado para ver detalhes e agir nele.": "Простой режим: ваши армии действуют сами. Коснитесь штата, чтобы увидеть детали и действовать.",
  "⚠ Encerra a campanha agora": "⚠ Сразу завершает кампанию",
  "🏁 Encerra a campanha agora": "🏁 Сразу завершает кампанию",
  "final intermediário": "промежуточная концовка",
  "No Fácil, a interface é simples: os exércitos agem sozinhos e Diplomacia e Facções ficam no botão “Mais”. Dá para mudar isso em Configurações.": "На лёгком уровне интерфейс простой: армии действуют сами, а Дипломатия и Фракции спрятаны под кнопкой «Ещё». Это можно изменить в Настройках.",
  "Exércitos no automático": "Армии на автомате",
  "No modo simples, seus exércitos agem sozinhos todo mês: atacam onde a chance é boa e defendem o resto. Você só precisa recrutar quando quiser mais tropas.": "В простом режиме ваши армии каждый месяц действуют сами: атакуют при хороших шансах и обороняются в остальных местах. Набирать войска нужно, только если хотите больше.",
  "Quer controlar cada exército? Clique em “Comandar manualmente”.": "Хотите управлять каждой армией? Нажмите «Командовать вручную».",
