  "Desligada": "Выключено",
  "Tem um acontecimento esperando sua resposta na aba História. O mês só avança depois que você escolher.": "На вкладке «История» вас ждёт событие. Месяц продолжится только после вашего выбора.",
  "Um exército está sem ordem neste mês. Deixe as tropas agirem sozinhas: elas atacam onde a chance é boa e defendem o resto.": "У одной армии в этом месяце нет приказа. Пусть войска действуют сами: атакуют при хороших шансах и обороняются в остальных местах.",
  "Já fizemos o que dava neste mês. Quando estiver pronto, encerre o mês.": "В этом месяце мы сделали всё, что могли. Когда будете готовы, завершите месяц.",
