  "Aceite o resultado e, no fim, escolha comandar a direita sem disputar o cargo (ou perca a eleição de 2026).": "Примите результат и в конце решите руководить правыми, не борясь за пост (или проиграйте выборы 2026 года).",
  "Deixe o Apoio Popular chegar a zero, ou insista na própria candidatura depois de ficar inelegível.": "Доведите народную поддержку до нуля или настаивайте на своей кандидатуре после лишения права избираться.",
  "Tente a ruptura sem Apoio Militar suficiente e decida permanecer no país.": "Попытайтесь пойти на разрыв без достаточной поддержки армии и решите остаться в стране.",
  "Tente a ruptura sem Apoio Militar suficiente e decida deixar o país.": "Попытайтесь пойти на разрыв без достаточной поддержки армии и решите покинуть страну.",
  "Siga a ruptura com Apoio Militar alto e vença a guerra até dominar quase todo o território.": "Идите на разрыв при высокой поддержке армии и выиграйте войну, захватив почти всю территорию.",
  "Durante a guerra, aceite um cessar-fogo com as linhas congeladas.": "Во время войны согласитесь на перемирие с замороженными линиями.",
  "No regime, perca a maioria dos estados ou negocie uma saída.": "При режиме потеряйте большинство штатов или договоритесь о выходе.",
  "Como a campanha termina": "Как заканчивается кампания",
  "Cada campanha acaba num dos finais da história: vitória, intermediário ou derrota.": "Каждая кампания заканчивается одной из концовок истории: победной, промежуточной или поражением.",
  "Na tela de final você recebe uma": "На экране концовки вы получаете",
  "nota de S a C": "оценку от S до C",
  ", um resumo da sua história e": ", сводку вашей истории и",
