  "O plano, passo a passo": "План, шаг за шагом",
  "Primeiro, um balanço discreto da derrota. Ninguém conspira sem saber quem ainda atende o telefone:": "Сначала — тихий разбор поражения. Никто не устраивает заговор, не зная, кто ещё берёт трубку:",
