  "Evitar a rebelião (Pacto Federativo) mantém uma frente só.": "Если избежать мятежа (Федеративный пакт), фронт останется один.",
  "Abriu uma nova frente de batalha. Divida as tropas entre as frentes na aba Mapa.": "Открылся новый фронт. Распределите войска между фронтами на вкладке «Карта».",
  "Começou a guerra: abriu a linha de frente. Na aba Mapa, escolha a postura de cada frente (avançar, segurar ou recuar) — não gasta AP.": "Война началась: линия фронта открыта. На вкладке «Карта» выберите позицию каждого фронта (наступать, держать или отступать) — это не тратит ОД.",
