  "Renovar a direita": "Обновить правых",
  "Depois do revés, abrir espaço para nomes novos, moderar o discurso e reconquistar o centro.": "После неудачи дать место новым именам, смягчить риторику и вернуть центр.",
  "Aparece depois de um revés: ficar inelegível ou perder uma eleição.": "Появляется после неудачи: лишение права избираться или проигранные выборы.",
  "Dobrar a aposta": "Удвоить ставку",
  "Depois do revés, culpar o sistema e manter a base fiel em pé de guerra. Mais apoio nas ruas, menos pontes.": "После неудачи обвинить систему и держать верную базу в боевой готовности. Больше поддержки на улицах, меньше мостов.",
