  "Aparece quando a Tensão no Sul passa de 55 (antes de qualquer rebelião).": "Появляется, когда напряжённость на Юге превышает 55 (до любого мятежа).",
  "Capitalizar a popularidade": "Монетизировать популярность",
  "A maré está a seu favor: transformar a popularidade em doações e filiações antes que ela passe.": "Ветер в ваши паруса: превратите популярность в пожертвования и новых членов партии, пока она не прошла.",
