  "força no placar do mapa: você": "сила на табло карты: вы",
  "× inimigo": "× противник",
  "No mapa: a linha de frente é a borda grossa laranja; faixas listradas mostram o seu lado e o lado inimigo; cada frente tem um placar com a sua força e a do inimigo.": "На карте: линия фронта — толстая оранжевая граница; полосатые зоны показывают вашу сторону и сторону противника; у каждого фронта есть табло с вашей силой и силой противника.",
  "O placar na linha mostra a sua força contra a do inimigo; toque nele para abrir a frente.": "Табло на линии показывает вашу силу против силы противника; нажмите на него, чтобы открыть фронт.",
