  "Inglês, chinês e russo cobrem todo o cenário 2022. O cenário 1964 ainda está só em português.": "Английский, китайский и русский переводы охватывают весь сценарий 2022. Сценарий 1964 пока только на португальском.",
  "Inglês, chinês e russo cobrem todo o cenário 2022": "Английский, китайский и русский переводы охватывают весь сценарий 2022",
