  "Regiões inimigas": "Регионы противника",
  "Você não move exércitos: escolha a postura de cada frente e encerre o mês.": "Вы не двигаете армии: выберите позицию каждого фронта и завершите месяц.",
  ", da economia, das tropas no estado e de haver guerra por perto.": ", экономики, войск в штате и наличия боёв поблизости.",
  "O governador de um estado na linha de frente manda emissários: aceita apoiar o regime em troca de verbas e cargos.": "Губернатор прифронтового штата присылает эмиссаров: готов поддержать режим в обмен на деньги и должности.",
  "Capital e reduto só caem com o cerco completo; enquanto isso, a linha toma as regiões em volta.": "Столица и оплот падают только после полной осады; пока она идёт, линия занимает окрестные регионы.",
