  "Diplomacia traduzida": "Дипломатия переведена",
  "A aba Diplomacia agora aparece inteira em inglês, chinês e russo: previsão, motivos, consequências e respostas dos países.": "Вкладка «Дипломатия» теперь полностью на английском, китайском и русском: прогноз, причины, последствия и ответы стран.",
  "Os relatórios do mês sobre dívidas, sanções e apoio estrangeiro também foram traduzidos.": "Ежемесячные отчёты о долгах, санкциях и иностранной поддержке тоже переведены.",
  "Custo": "Стоимость",
