  "Oportunidade aberta na aba Decisões: último mês para começar. Depois de começada, ela sempre termina. Vale aproveitar:": "Возможность во вкладке «Решения»: последний месяц, чтобы начать. Начатая — всегда завершается. Стоит воспользоваться:",
