  "num país dividido, com inflação acima de {0}% ao ano e resistência armada possível no Rio Grande do Sul.": "в расколотой стране с инфляцией выше {0}% в год и возможным вооружённым сопротивлением в Риу-Гранди-ду-Сул.",
  "O mapa usa a divisão atual dos estados; passe o mouse para ver a situação de {0}.": "Карта использует нынешнее деление на штаты; наведите курсор, чтобы увидеть ситуацию {0} года.",
