  "O TSE confirma a derrota no {0}º turno por {1} ponto. Reconhecer o resultado, contestar, ficar em silêncio — ou tentar romper a ordem constitucional? Instituições, quartéis, ruas e o mundo vão reagir.": "Высший избирательный суд подтверждает ваше поражение во {0}-м туре с разницей в {1} п. п. Признать результат, оспорить, промолчать — или попытаться разрушить конституционный порядок? Институты, казармы, улицы и мир ответят.",
