  "Goulart caiu. Você comanda o governo instalado pelos militares. Devolver o poder aos civis em {0} ou endurecer com atos institucionais, cassações e censura? Linha dura, Congresso, Igreja, estudantes, o Sul de Brizola e Washington vão pressionar.": "Гуларт пал. Вы возглавляете правительство, поставленное военными. Вернуть власть гражданским в {0} году или ужесточить режим институциональными актами, лишением мандатов и цензурой? Сторонники жёсткой линии, Конгресс, Церковь, студенты, Юг Бризолы и Вашингтон будут давить.",
