  "E se a noite de {0} de outubro de {1} tivesse terminado de outro jeito?": "Что, если бы ночь {0} октября {1} года закончилась иначе?",
  "{0} de outubro de {1}. A apuração termina com a menor margem da história recente: o candidato da oposição vence o {2}º turno com {3}% dos votos válidos. Você joga como o presidente derrotado, Jair Bolsonaro, nas horas e meses seguintes.": "{0} октября {1} года. Подсчёт завершается с минимальным отрывом в новейшей истории: кандидат оппозиции побеждает во {2}-м туре с {3}% действительных голосов. Вы играете за проигравшего президента Жаира Болсонару в последующие часы и месяцы.",
  "O mapa começa com o resultado real do {0}º turno em cada estado. A partir da primeira decisão, a história se torna alternativa: suas escolhas movem o apoio popular, os quartéis, o Congresso e o olhar do mundo — e podem levar o país da transição pacífica à ruptura e até a uma guerra de separação.": "Карта начинается с реальных итогов {0}-го тура в каждом штате. С первого решения история становится альтернативной: ваши выборы влияют на народную поддержку, казармы, Конгресс и взгляд мира — и могут привести страну от мирной передачи власти к разрыву и даже к войне за отделение.",
