  "Não dá bônus mensal: o que importa é evitar a crise (lealdade < {0} com influência ≥ {1}).": "Нет ежемесячного бонуса: главное — избежать кризиса (лояльность < {0} при влиянии ≥ {1}).",
  "({0} Recursos · sem gastar ações): lealdade +{1}; Militares −{2} de lealdade (rival).": "({0} ресурсов · без траты действий): лояльность +{1}; военные −{2} лояльности (соперник).",
