  "Teto de {0}.": "Потолок {0}.",
  ": {0} para agradar, {1} para enfraquecer —": ": {0} — задобрить, {1} — ослабить —",
  ": {0} → +{1} ação ({2}×/turno).": ": {0} → +{1} действие ({2}×/ход).",
  "Abaixo de zero, você perde {0} de Apoio Popular por mês.": "Ниже нуля вы теряете {0} народной поддержки в месяц.",
  "Pontos de ação do turno. Quase tudo custa {0} AP. Recarregam a cada mês e não acumulam. Em {1}: {2} de base, {3} com Apoio Popular {4}+, {5} com {6}+; +{7} comprando com Recursos ({8}×/turno).": "Очки действий на ход. Почти всё стоит {0} ОД. Восстанавливаются каждый месяц и не копятся. В {1}: база {2}, {3} при народной поддержке {4}+, {5} при {6}+; +{7} за ресурсы ({8}×/ход).",
  "opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas. Se chegar a zero, a campanha termina.": "общественное мнение. Высокое успокаивает штаты и в {0} даёт больше действий за ход ({1}+ → {2}, {3}+ → {4}); низкое подпитывает протесты и восстания. Если упадёт до нуля, кампания окончена.",
  "Tensão em cada estado ({0}–{1}). Média acima de {2} nos seus estados derruba o apoio; um estado acima de {3} sem tropas pode se revoltar. Investir, fazer propaganda e negociar com o governador baixam a agitação.": "Напряжённость в каждом штате ({0}–{1}). Среднее выше {2} в ваших штатах снижает поддержку; штат выше {3} без войск может восстать. Инвестиции, пропаганда и переговоры с губернатором снижают волнения.",
  "Lealdade (do seu lado?) e influência (quanto pesam). Lealdade abaixo de {0} com influência {1} ou mais gera crises.": "Лояльность (на вашей ли стороне?) и влияние (насколько весомы). Лояльность ниже {0} при влиянии {1} и выше вызывает кризисы.",
  "(em fases calmas, até {0} meses).": "(в спокойных фазах — до {0} мес.).",
  "{0} de base; com": "{0} базовых; при",
  "Apoio Popular {0}+": "народной поддержке {0}+",
  "são {0}, e com": "— {0}, а при",
  "são {0}. Também dá para": "— {0}. Также можно",
  "comprar +{0}": "купить +{0}",
  "Teto de {0}:": "Потолок {0}:",
  ": opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas.": ": общественное мнение. Высокое успокаивает штаты и в {0} даёт больше действий за ход ({1}+ → {2}, {3}+ → {4}); низкое подпитывает протесты и восстания.",
  "Vão de {0} a {1}.": "Диапазон от {0} до {1}.",
  "Cria um novo exército por alguns Recursos, sem AP (até {0} por mês). Exércitos fracos em descanso no seu território também se reforçam sozinhos.": "Создаёт новую армию за ресурсы, без ОД (до {0} в месяц). Слабые армии, отдыхающие на вашей территории, тоже пополняются сами.",
  "({0} AP); ele avança a cada mês e, ao concluir, aplica efeitos e libera ações, eventos e opções.": "({0} ОД); он продвигается каждый месяц и по завершении даёт эффекты и открывает действия, события и варианты.",
  "lealdade abaixo de {0} com influência {1} ou mais provoca uma": "лояльность ниже {0} при влиянии {1} и выше вызывает",
  "que têm de você (−{0} a +{1}). Escolha um para negociar.": "о вас (от −{0} до +{1}). Выберите одного для переговоров.",
  "mostra a chance antes de propor ({0} AP). A": "показывает шансы до предложения ({0} ОД).",
  "Você não impediu a transição. A equipe do presidente eleito assume os ministérios e, em {0}º de janeiro, a faixa presidencial muda de dono. O comando do país começa a escapar das suas mãos.": "Вы не помешали передаче власти. Команда избранного президента принимает министерства, и {0} января президентская лента меняет владельца. Управление страной начинает ускользать из ваших рук.",
  "A posse acontece em {0}º de janeiro. Uma semana depois, milhares de manifestantes invadem e depredam as sedes do Congresso, do Planalto e do STF. As imagens correm o mundo; líderes estrangeiros condenam o ataque em uníssono.": "Инаугурация проходит {0} января. Через неделю тысячи людей врываются в здания Конгресса, Планалту и Верховного суда и громят их. Кадры облетают весь мир; иностранные лидеры единодушно осуждают нападение.",
  "O Brasil, que entrou em {0} como um país polarizado, agora corre o risco de não ser mais um país.": "Бразилия, вошедшая в {0} год поляризованной страной, теперь рискует перестать быть страной.",
  "Por maioria, o tribunal declara você inelegível por oito anos. A decisão cai como uma bomba na direita: governadores, pastores, empresários e deputados começam a se perguntar quem herdará os seus votos em {0}.": "Большинством голосов суд лишает вас права избираться на восемь лет. Решение взрывается бомбой среди правых: губернаторы, пасторы, предприниматели и депутаты начинают гадать, кто унаследует ваши голоса в {0} году.",
  "Escolher e apoiar um herdeiro político para {0}.": "Выбрать и поддержать политического наследника на {0} год.",
