  "+{0}% ao segurar a linha; −{1}% ao avançar.": "+{0}% при удержании линии; −{1}% при наступлении.",
  "+{0} de suprimento por mês, +{1}% em tudo e recua com menos perda de terreno.": "+{0} снабжения в месяц, +{1}% ко всему, при отступлении теряет меньше территории.",
  "Alistamento: +{0} de tropas para o seu efetivo.": "Набор: +{0} войск к вашим силам.",
  "linha +{0} (agora {1}/{2}). Baixas: suas {3}, inimigas {4}.": "линия +{0} (теперь {1}/{2}). Потери: ваши {3}, противника {4}.",
