  "+{0} de tropas recrutadas (−{1}). Elas entram nas frentes já neste mês.": "Набрано +{0} войск (−{1}). Они выйдут на фронты уже в этом месяце.",
  "+{0}% de força e avanço maior; se falhar, perde moral e tropas.": "+{0}% силы и более глубокое продвижение; при неудаче — потеря боевого духа и войск.",
  "de cada frente e encerre o mês. A cada +{0} a linha toma um estado; a −{1}, perde um.": "каждого фронта и завершите месяц. При +{0} линия берёт штат; при −{1} — теряет.",
