  "Santa Catarina pode aderir em {0} meses se a tensão continuar alta.": "Санта-Катарина может присоединиться через {0} мес., если напряжённость останется высокой.",
  "Mais tropas por alguns Recursos, sem AP (até {0} vezes por mês). Elas entram nas frentes já neste mês, divididas entre elas.": "Больше войск за немного ресурсов, без ОД (до {0} раз в месяц). Они выйдут на фронты уже в этом месяце и распределятся между ними.",
  "Apareceu uma oportunidade na aba Decisões e ela some em {0} meses. Vale aproveitar:": "Во вкладке «Решения» появилась возможность, она исчезнет через {0} мес. Стоит воспользоваться:",
