  "(metade das regiões do estado passa para o inimigo); fora dela, grandes protestos (−{0} de apoio) ou até perder o estado.": "(половина регионов штата переходит к противнику); вне войны — массовые протесты (−{0} поддержки) или даже потеря штата.",
