  "Receita da quinzena: {0} Recursos.": "Доход за полмесяца: {0} Ресурсов.",
  "Próximo evento-chave da história em cerca de {0} quinzenas.": "Следующее ключевое событие сюжета — примерно через {0} полумесяц(а).",
  "{0} quinzena": "{0} полмесяца",
  "{0} quinzenas": "{0} полмесяца",
  "{0}/{1} quinzena": "{0}/{1} полмесяца",
  "{0}/{1} quinzenas": "{0}/{1} полмесяца",
  "No começo da campanha cada turno é uma quinzena ({0} dias): mais decisões antes da posse. Depois, cada turno vira um mês.": "В начале кампании каждый ход — полмесяца ({0} дней): больше решений до инаугурации. Потом каждый ход становится месяцем.",
  "Contestação das urnas: progresso {0}/{1} (+{2}) · credibilidade {3} · escalada {4}.": "Оспаривание выборов: прогресс {0}/{1} (+{2}) · доверие {3} · эскалация {4}.",
  "Contestação das urnas: progresso {0}/{1} · credibilidade {2} · escalada {3}.": "Оспаривание выборов: прогресс {0}/{1} · доверие {2} · эскалация {3}.",
  "Contestação das urnas: progresso {0} de {1}, credibilidade {2}, escalada {3}. Abrir detalhes.": "Оспаривание выборов: прогресс {0} из {1}, доверие {2}, эскалация {3}. Открыть подробности.",
  "Julgamento no TSE: precisa de {0}": "Решение ВИС: нужно {0}",
  "Veredito: precisa de {0}": "Вердикт: нужно {0}",
  "Chegue a {0} para vencer": "Дойдите до {0}, чтобы победить",
  "Seu progresso está baixo para o julgamento de janeiro ({0}/{1}). Auditoria, ações no TSE e o Congresso rendem mais com credibilidade alta.": "Ваш прогресс низок для январского решения ({0}/{1}). Аудит, иски в ВИС и Конгресс дают больше при высоком доверии.",
  "As ruas estão no limite (escalada {0}). Mais um ato e os acampamentos viram caso de quartel. Use 'Baixar a temperatura' agora.": "Улицы на пределе (эскалация {0}). Ещё одна акция — и лагерями займутся казармы. Используйте «Снизить градус» сейчас.",
  "Sua credibilidade está em {0}. Abaixo de zero, o TSE declara você inelegível. Pare com as redes e traga observadores ou peritos.": "Ваше доверие — {0}. Ниже нуля ВИС лишит вас права баллотироваться. Прекратите кампанию в соцсетях и привлеките наблюдателей или экспертов.",
  "Está funcionando: {0}/{1} de progresso, credibilidade {2}, escalada {3}. Mantenha a frente dentro da lei.": "Работает: прогресс {0}/{1}, доверие {2}, эскалация {3}. Держите фронт в рамках закона.",
  "Agora é pelas regras, mas é guerra de nervos. Três números: o progresso vence em {0}; a credibilidade não pode zerar, ou o TSE te torna inelegível; e a escalada não pode chegar a {1}, ou as ruas viram caso de quartel.": "Теперь всё по правилам, но это война нервов. Три числа: прогресс побеждает на {0}; доверие не должно упасть до нуля, иначе ВИС лишит вас права баллотироваться; эскалация не должна дойти до {1}, иначе улицами займутся казармы.",
  "O TSE adiou a posse para auditar as seções. Até março, cada quinzena conta: leve o progresso a {0} sem perder a credibilidade.": "ВИС отложил инаугурацию ради аудита участков. До марта важна каждая половина месяца: доведите прогресс до {0}, не потеряв доверия.",
  "Você está tentando virar o resultado sem guerra: auditorias, tribunais, Congresso e ruas, sempre dentro da lei. São três números de {0} a {1}:": "Вы пытаетесь перевернуть результат без войны: аудиты, суды, Конгресс и улицы, всегда в рамках закона. Три числа от {0} до {1}:",
  "Progresso {0}/{1}": "Прогресс {0}/{1}",
  "Credibilidade {0}": "Доверие {0}",
  "Escalada {0}": "Эскалация {0}",
  "em {0}, o TSE anula o resultado e você vence": "на {0} ВИС аннулирует результат, и вы побеждаете",
  "em {0}, você fica inelegível (derrota)": "на {0} вы теряете право баллотироваться (поражение)",
  "em {0}, as ruas saem do controle e a crise vai para os quartéis": "на {0} улицы выходят из-под контроля, и кризис переходит в казармы",
  "com {0} ou mais de progresso, a posse é adiada e a disputa continua; abaixo disso, a contestação acaba.": "при прогрессе {0} и выше инаугурацию откладывают и борьба продолжается; ниже — оспаривание заканчивается.",
  "só vence com {0}. Com credibilidade muito baixa, o TSE declara você inelegível.": "победа только при {0}. При очень низком доверии ВИС лишит вас права баллотироваться.",
  "Progresso: as ações abaixo, os focos do ramo “Contestação institucional” (aba Decisões) e as escolhas nos eventos. Também sobe sozinho com Apoio Popular, Base Política e Centrão altos (agora +{0} por quinzena).": "Прогресс: действия ниже, фокусы ветки «Институциональное оспаривание» (вкладка «Решения») и выбор в событиях. Он также растёт сам при высоких Народной поддержке, Политической базе и Сентране (сейчас +{0} за полмесяца).",
  "Credibilidade multiplica o progresso (agora ×{0}): redes e ataques aos ministros a derrubam; peritos, observadores e calma a recuperam.": "Доверие умножает прогресс (сейчас ×{0}): соцсети и нападки на судей его снижают; эксперты, наблюдатели и спокойствие восстанавливают.",
  "Escalada: atos e bloqueios esquentam as ruas; ela esfria {0} por quinzena e com “Baixar a temperatura”. Acima de {1}, também corrói a credibilidade.": "Эскалация: акции и блокады накаляют улицы; она остывает на {0} за полмесяца и от «Снизить градус». Выше {1} она также подтачивает доверие.",
  "A contestação chegou a {0}: o TSE anulou o resultado e convocou uma nova votação.": "Оспаривание дошло до {0}: ВИС аннулировал результат и назначил новое голосование.",
